import type { SatForm, SatQuestion } from "./types";

/**
 * Practice Test 9 — full-length adaptive form (original, hand-verified items).
 * R&W: 27 + 27 + 27 (m1 / m2easy / m2hard).
 * Math: 22 + 22 + 22 (m1 / m2easy / m2hard).
 * Topics are deliberately distinct from Tests 1–8.
 */

// ─────────────────────────── R&W MODULE 1 (mixed, 27) ───────────────────────────
const T9_RW_M1: SatQuestion[] = [
  { id: "t9rw1-1", section: "rw", domain: "Craft and Structure", difficulty: "med", passage: "The diplomat's remarks were carefully ______, designed to soothe both sides without committing her government to anything.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["measured", "reckless", "spontaneous", "hostile"], correct: 0, explanation: "The blank describes remarks that are 'carefully' controlled to soothe both sides while avoiding any commitment. 'Measured' means deliberately restrained and weighed, which fits speech crafted to give nothing away. (B) 'reckless' is the opposite of careful and would risk committing the government. (C) 'spontaneous' contradicts 'carefully,' which signals planning, not impulse. (D) 'hostile' would inflame rather than soothe both sides. The answer is A." },
  { id: "t9rw1-2", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "The team of researchers ______ submitting its final report next week.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["is", "are", "were", "have"], correct: 0, explanation: "Subject-verb agreement: the grammatical subject is the collective noun 'team,' which is singular and takes a singular verb. The prepositional phrase 'of researchers' sits between the subject and verb to tempt you toward a plural, but the object of a preposition can never be the subject. So the verb must agree with 'team' = 'is.' (B) 'are' and (C) 'were' are plural and wrongly agree with 'researchers.' (D) 'have' is plural and also fails the present-tense singular requirement. The answer is A." },
  { id: "t9rw1-3", section: "rw", domain: "Information and Ideas", difficulty: "med", passage: "Mangrove forests trap sediment with their dense roots, building up coastlines and shielding inland areas from storm surges.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["Mangroves protect and extend coastlines by trapping sediment.", "Mangroves grow only far inland.", "Mangroves erode the shoreline.", "Mangroves cannot survive near salt water."], correct: 0, explanation: "The text makes two claims about mangroves: their roots 'build up coastlines' (extending them) and they 'shield inland areas from storm surges' (protecting them). Choice A captures both ideas, so it states the main idea. (B) is contradicted by 'coastlines' and 'inland areas,' which place mangroves at the shore, not far inland. (C) reverses the text: roots 'trap sediment' and 'build up' the coast, the opposite of eroding it. (D) is unsupported and false to fact; the passage describes coastal mangroves thriving in a salt-water environment. The answer is A." },
  { id: "t9rw1-4", section: "rw", domain: "Expression of Ideas", difficulty: "med", passage: "The factory cut its energy use sharply. ______, its production levels stayed exactly the same.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["Therefore", "Nevertheless", "For instance", "Likewise"], correct: 1, explanation: "The first sentence says the factory 'cut its energy use sharply'; the second says production 'stayed exactly the same.' You would expect less energy to mean less output, so the second sentence defies that expectation. A contrast transition is needed: 'Nevertheless' signals 'despite that.' (A) 'Therefore' marks a result, but unchanged output is not a consequence of cutting energy. (C) 'For instance' introduces an example, but the second sentence is not an example of the first. (D) 'Likewise' marks similarity, but the two facts pull in opposite directions. The answer is B." },
  { id: "t9rw1-5", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "The recipe calls for three spices ______ cumin, coriander, and turmeric.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["spices, ", "spices: ", "spices; ", "spices "], correct: 1, explanation: "Punctuation rule: a colon follows a complete, independent clause and introduces an explanation or list. 'The recipe calls for three spices' is a complete sentence, and what follows ('cumin, coriander, and turmeric') names those three spices, so a colon is correct. (A) a comma is too weak to formally introduce the list and creates a run-on feel here. (C) a semicolon must join two independent clauses, but the list that follows is not a clause. (D) no punctuation leaves the introductory clause and the list improperly fused. The answer is B." },
  { id: "t9rw1-6", section: "rw", domain: "Craft and Structure", difficulty: "med", passage: "Although brief, the apology felt ______, and the audience sensed at once that it was sincere.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["heartfelt", "grudging", "rehearsed", "hollow"], correct: 0, explanation: "The clause 'the audience sensed at once that it was sincere' defines the blank: the apology felt genuine. 'Heartfelt' means deeply and sincerely felt, matching 'sincere.' (B) 'grudging' means reluctant, which undercuts sincerity. (C) 'rehearsed' implies calculated performance rather than genuine feeling. (D) 'hollow' means empty or insincere, the direct opposite of what the audience sensed. The answer is A." },
  { id: "t9rw1-7", section: "rw", domain: "Information and Ideas", difficulty: "med", passage: "The pass is open to hikers only from June through September; in all other months heavy snow makes it impassable.", prompt: "Which statement is best supported by the text?", type: "mcq", choices: ["A hiker cannot use the pass in February.", "The pass is open all year.", "Snow never falls on the pass.", "The pass is busiest in winter."], correct: 0, explanation: "The text states the pass is open 'only from June through September' and that 'in all other months heavy snow makes it impassable.' February falls outside June–September, so it is one of those impassable months; a hiker cannot use it then. Choice A follows directly. (B) contradicts 'only from June through September.' (C) contradicts 'heavy snow' in the off months. (D) is impossible since winter snow makes the pass impassable, not busy. The answer is A." },
  { id: "t9rw1-8", section: "rw", domain: "Expression of Ideas", difficulty: "med", passage: "The museum digitized its rare manuscripts. ______, scholars on other continents can now study them without traveling.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["However", "As a result", "Otherwise", "In contrast"], correct: 1, explanation: "The first sentence is a cause ('digitized its rare manuscripts'); the second is the effect ('scholars on other continents can now study them without traveling'). Digitizing is exactly what makes remote study possible, so a cause-and-effect transition fits: 'As a result.' (A) 'However' and (D) 'In contrast' both signal opposition, but the two sentences agree. (C) 'Otherwise' means 'if not,' introducing an alternative that does not apply. The answer is B." },
  { id: "t9rw1-9", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "Each of the volunteers ______ assigned a different neighborhood to survey.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["were", "was", "are", "have been"], correct: 1, explanation: "Subject-verb agreement: 'Each' is an indefinite pronoun that is always singular and takes a singular verb. The phrase 'of the volunteers' is a prepositional phrase whose plural object ('volunteers') tempts a plural verb, but it cannot govern the verb. The singular past form 'was' agrees with 'Each.' (A) 'were' and (C) 'are' are plural. (D) 'have been' is also plural. The answer is B." },
  { id: "t9rw1-10", section: "rw", domain: "Craft and Structure", difficulty: "med", passage: "The professor's lectures were famously ______, weaving history, art, and economics into a single thread.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["wide-ranging", "narrow", "repetitive", "dull"], correct: 0, explanation: "The detail 'weaving history, art, and economics into a single thread' shows lectures that span many fields, so the blank needs a word meaning broad in scope. 'Wide-ranging' fits precisely. (B) 'narrow' is the opposite of covering several disciplines. (C) 'repetitive' would mean repeating the same thing, not combining diverse subjects. (D) 'dull' describes tone, not breadth, and 'famously' here is a compliment, not a criticism. The answer is A." },
  { id: "t9rw1-11", section: "rw", domain: "Information and Ideas", difficulty: "med", passage: "A survey found that 80 percent of commuters who switched to cycling reported lower stress, while only 30 percent reported faster trips.", prompt: "Which statement is best supported by the data?", type: "mcq", choices: ["More cyclists noticed lower stress than noticed faster trips.", "Cycling made trips faster for everyone.", "No cyclists felt less stress.", "Most cyclists reported faster trips."], correct: 0, explanation: "The data give two figures: 80 percent reported lower stress and 30 percent reported faster trips. Since 80 > 30, more cyclists noticed lower stress than noticed faster trips, exactly what choice A states. (B) 'everyone' is false; only 30 percent reported faster trips. (C) contradicts the 80 percent who felt less stress. (D) is wrong because 30 percent is a minority, not 'most.' The answer is A." },
  { id: "t9rw1-12", section: "rw", domain: "Expression of Ideas", difficulty: "med", passage: "Solar panels were once prohibitively expensive. ______, their price has fallen so far that they now rival fossil fuels.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["Similarly", "Today", "Therefore", "Furthermore"], correct: 1, explanation: "The first sentence describes the past ('were once prohibitively expensive'); the second describes the present state ('their price has fallen so far'). The contrast is between then and now, so a time marker that pivots to the present is needed: 'Today.' (A) 'Similarly' marks likeness, but past and present prices differ sharply. (C) 'Therefore' marks a result, yet the price drop is not caused by the panels having been expensive. (D) 'Furthermore' adds a similar point, but this is a change over time, not an addition. The answer is B." },
  { id: "t9rw1-13", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "The architect designed the bridge, oversaw its construction, and ______ its opening ceremony.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["attending", "attended", "to attend", "attends"], correct: 1, explanation: "Parallel structure: items in a series must share the same grammatical form. The sentence lists 'designed the bridge, oversaw its construction, and ______ its opening ceremony' - two simple past-tense verbs. The third item must match, so 'attended.' (A) 'attending' is a participle, breaking the parallel. (C) 'to attend' is an infinitive, also nonparallel. (D) 'attends' is present tense and clashes with the past-tense 'designed' and 'oversaw.' The answer is B." },
  { id: "t9rw1-14", section: "rw", domain: "Craft and Structure", difficulty: "med", passage: "The witness gave a ______ account, recalling details that even the investigators had overlooked.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["meticulous", "careless", "hazy", "brief"], correct: 0, explanation: "The clause 'recalling details that even the investigators had overlooked' shows an account that is extremely thorough and precise. 'Meticulous' means careful about fine detail, which fits exactly. (B) 'careless' is the opposite of noticing overlooked details. (C) 'hazy' means vague and unclear, contradicting the sharp recall described. (D) 'brief' refers to length, not the rich detail the sentence emphasizes. The answer is A." },
  { id: "t9rw1-15", section: "rw", domain: "Information and Ideas", difficulty: "med", passage: "The grant funds research only in renewable energy; proposals on other topics are returned without review.", prompt: "Which statement is best supported by the text?", type: "mcq", choices: ["A proposal on wind power could be considered for the grant.", "Any research topic qualifies for the grant.", "Renewable-energy proposals are rejected automatically.", "The grant reviews all proposals it receives."], correct: 0, explanation: "The text says the grant 'funds research only in renewable energy' and that other topics are 'returned without review.' Wind power is a form of renewable energy, so a wind-power proposal would qualify for consideration - choice A. (B) is contradicted by 'only in renewable energy.' (C) reverses the text: renewable-energy proposals are precisely the ones funded, not rejected. (D) is false because off-topic proposals are 'returned without review,' so not all are reviewed. The answer is A." },
  { id: "t9rw1-16", section: "rw", domain: "Expression of Ideas", difficulty: "med", passage: "The startup missed its first deadline. ______, it lost the confidence of two early investors.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["Nonetheless", "Consequently", "However", "Meanwhile"], correct: 1, explanation: "The first sentence is a cause ('missed its first deadline'); the second is its effect ('lost the confidence of two early investors'). Investors losing confidence is a direct result of the missed deadline, so a cause-and-effect transition fits: 'Consequently.' (A) 'Nonetheless' and (C) 'However' both signal contrast, but the two sentences agree in direction. (D) 'Meanwhile' marks simultaneity, not causation, and the loss follows from the miss rather than merely happening alongside it. The answer is B." },
  { id: "t9rw1-17", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "The novelist published her debut in 2010 ______ she had been writing privately for nearly a decade before that.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["2010, but", "2010 but", "2010; but", "2010: but"], correct: 0, explanation: "Both halves are independent clauses ('The novelist published her debut in 2010' and 'she had been writing privately...'). The rule for joining two independent clauses with a coordinating conjunction (FANBOYS, here 'but') is comma + conjunction. So 'comma + but' is correct. (B) 'but' with no comma creates a comma splice error in reverse - a coordinating conjunction joining two clauses needs the comma. (C) a semicolon should not be paired with a coordinating conjunction; semicolons replace it. (D) a colon needs the first clause to introduce the second, which it does not here. The answer is A." },
  { id: "t9rw1-18", section: "rw", domain: "Craft and Structure", difficulty: "med", passage: "Rather than condemning the old theory outright, the paper treats it as a ______ — useful in its day, now superseded.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["stepping-stone", "dead end", "fabrication", "masterpiece"], correct: 0, explanation: "The dash explains the blank: the theory was 'useful in its day, now superseded.' A 'stepping-stone' is something valuable that you stand on to move past it, which captures both its past usefulness and its having been left behind. (B) 'dead end' implies the theory led nowhere, contradicting 'useful in its day.' (C) 'fabrication' means a deliberate lie, but the text treats the theory as honestly useful, not false. (D) 'masterpiece' implies lasting greatness, contradicting 'now superseded.' The answer is A." },
  { id: "t9rw1-19", section: "rw", domain: "Information and Ideas", difficulty: "med", passage: "The author begins by recounting a personal failure, then uses it to introduce the broader argument that mistakes drive learning.", prompt: "Which choice best describes the function of the personal failure?", type: "mcq", choices: ["It serves as a concrete entry point into the author's larger argument.", "It states the essay's final conclusion.", "It lists unrelated definitions.", "It contradicts the author's thesis."], correct: 0, explanation: "The text says the author 'begins by recounting a personal failure, then uses it to introduce the broader argument.' The failure therefore functions as a concrete way into the larger point, exactly what choice A says ('a concrete entry point into the author's larger argument'). (B) is wrong because the failure opens the essay; it is not the 'final conclusion.' (C) is unsupported: a single personal story is not a list of 'unrelated definitions.' (D) is wrong because the failure illustrates and introduces the thesis ('mistakes drive learning') rather than contradicting it. The answer is A." },
  { id: "t9rw1-20", section: "rw", domain: "Expression of Ideas", difficulty: "med", passage: "The vaccine requires storage at very low temperatures. ______, distributing it to rural clinics has proved difficult.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["For this reason", "By contrast", "Even so", "Nonetheless"], correct: 0, explanation: "The first sentence states a demanding condition ('storage at very low temperatures'); the second states a consequence ('distributing it to rural clinics has proved difficult'). The cold-storage requirement is the cause of the distribution problem, so a cause-and-effect transition fits: 'For this reason.' (B) 'By contrast' and (D) 'Nonetheless' signal opposition, but the two sentences agree in direction. (C) 'Even so' concedes a contrast that does not exist here. The answer is A." },
  { id: "t9rw1-21", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "The orchestra, along with its guest soloists, ______ tuning before the performance.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["are", "is", "were", "have"], correct: 1, explanation: "Subject-verb agreement: the subject is the singular 'orchestra.' A phrase set off by commas with 'along with' is parenthetical and does NOT change the number of the subject (unlike 'and,' which would create a compound subject). So the verb stays singular: 'is.' (A) 'are,' (C) 'were,' and (D) 'have' are all plural and wrongly treat 'guest soloists' as part of the subject. The answer is B." },
  { id: "t9rw1-22", section: "rw", domain: "Craft and Structure", difficulty: "med", passage: "The critic praised the film's ______ tone, which moved easily between comedy and grief without jarring the viewer.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["versatile", "monotonous", "rigid", "shrill"], correct: 0, explanation: "The clause 'which moved easily between comedy and grief without jarring the viewer' defines the blank: a tone able to shift smoothly among different moods. 'Versatile' means adaptable to many uses or modes, which fits. (B) 'monotonous' means unchanging, the opposite of moving between moods. (C) 'rigid' means inflexible, contradicting 'moved easily.' (D) 'shrill' means harshly loud, which clashes with a tone praised for not jarring the viewer. The answer is A." },
  { id: "t9rw1-23", section: "rw", domain: "Information and Ideas", difficulty: "med", passage: "All ticket holders receive a printed program; members also receive a backstage tour.", prompt: "Which statement is best supported by the text?", type: "mcq", choices: ["A member receives both a program and a backstage tour.", "Non-members receive the backstage tour.", "No one receives a printed program.", "Members do not receive a program."], correct: 0, explanation: "The text states 'All ticket holders receive a printed program' and 'members also receive a backstage tour.' A member is a ticket holder, so a member gets the program (as everyone does) plus the tour (as members do) - both, exactly choice A. (B) is wrong: the tour is given to 'members,' not to non-members. (C) contradicts 'All ticket holders receive a printed program.' (D) is the opposite of that same statement, since members are ticket holders too. The answer is A." },
  { id: "t9rw1-24", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "Walking through the quiet gallery, ______ noticed a small painting tucked into a corner.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["the painting", "she", "there", "it"], correct: 1, explanation: "Modifier rule: an introductory participial phrase ('Walking through the quiet gallery') must modify the noun that immediately follows it, and only a person can do the walking. The subject right after the comma must therefore name that person: 'she.' (A) 'the painting' creates a dangling modifier - the painting was not walking. (C) 'there' is an expletive with no one to walk. (D) 'it' cannot perform the human action of walking through a gallery and noticing a painting. The answer is B." },
  { id: "t9rw1-25", section: "rw", domain: "Craft and Structure", difficulty: "med", passage: "His optimism was not naive but ______ — earned through years of setbacks he had learned to outlast.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["hard-won", "effortless", "groundless", "fleeting"], correct: 0, explanation: "The structure 'not naive but ______' calls for a word opposite to naive, and the dash explains it: the optimism was 'earned through years of setbacks he had learned to outlast.' 'Hard-won' means achieved through great effort, fitting something earned over years. (B) 'effortless' contradicts 'earned through years of setbacks.' (C) 'groundless' means baseless, but this optimism is grounded in lived experience. (D) 'fleeting' means short-lived, which says nothing about being earned and clashes with optimism that endured setbacks. The answer is A." },
  { id: "t9rw1-26", section: "rw", domain: "Information and Ideas", difficulty: "med", passage: "Whereas the older map relied on guesswork for uncharted regions, the new one is built entirely from satellite imagery.", prompt: "Which choice best describes the main purpose of the text?", type: "mcq", choices: ["To contrast the methods behind two maps.", "To argue that guesswork is best.", "To describe only the older map.", "To dismiss satellite imagery as unreliable."], correct: 0, explanation: "The sentence is built on 'Whereas the older map relied on guesswork ... the new one is built entirely from satellite imagery.' 'Whereas' signals a contrast, and the two halves compare the methods behind two maps - exactly choice A. (B) is wrong: the text describes guesswork as the old, replaced method, not the 'best' one. (C) is wrong because both maps are discussed, not only the older one. (D) reverses the point: satellite imagery is presented as the improvement, not as unreliable. The answer is A." },
  { id: "t9rw1-27", section: "rw", domain: "Expression of Ideas", difficulty: "med", passage: "The trail crew cleared the fallen trees and rebuilt the washed-out steps. ______, hikers were able to return to the route within days.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["Thus", "However", "Instead", "Otherwise"], correct: 0, explanation: "The first sentence is a cause ('cleared the fallen trees and rebuilt the washed-out steps'); the second is the effect ('hikers were able to return ... within days'). The repairs are what make the return possible, so a result transition fits: 'Thus.' (B) 'However' and (C) 'Instead' signal contrast or replacement, but the two sentences agree. (D) 'Otherwise' means 'if not,' introducing a hypothetical alternative that does not apply. The answer is A." },
];

// ─────────────────────────── R&W MODULE 2 EASY (easy/med, 27) ───────────────────────────
const T9_RW_M2E: SatQuestion[] = [
  { id: "t9rw2e-1", section: "rw", domain: "Craft and Structure", difficulty: "easy", passage: "The soup was too ______, so I added more water to thin it out.", prompt: "Which choice completes the text with the most logical word?", type: "mcq", choices: ["thick", "thin", "cold", "sweet"], correct: 0, explanation: "The clause 'so I added more water to thin it out' shows the soup needed thinning, which means it started out too 'thick.' (B) 'thin' is the opposite; you would not add water to thin something already thin. (C) 'cold' and (D) 'sweet' are not problems that adding water would fix, so neither matches the cause-and-effect logic of the sentence. The answer is A." },
  { id: "t9rw2e-2", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "The dogs ______ barking at the mail carrier.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["is", "are", "was", "am"], correct: 1, explanation: "Subject-verb agreement: the subject 'dogs' is plural and the action is happening now, so it takes the plural present-tense verb 'are.' (A) 'is' is singular. (C) 'was' is singular and past tense. (D) 'am' is the first-person singular form used only with 'I.' The answer is B." },
  { id: "t9rw2e-3", section: "rw", domain: "Information and Ideas", difficulty: "easy", passage: "Plants use sunlight, water, and air to make their own food through a process called photosynthesis.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["Plants make their own food using sunlight, water, and air.", "Plants eat other animals for food.", "Plants do not need sunlight.", "Plants cannot make food at all."], correct: 0, explanation: "The text says plants 'use sunlight, water, and air to make their own food' through photosynthesis. Choice A restates exactly that: plants make their own food from those three inputs. (B) is false; the passage says plants make food themselves, not by eating animals. (C) contradicts 'use sunlight.' (D) contradicts 'make their own food.' The answer is A." },
  { id: "t9rw2e-4", section: "rw", domain: "Expression of Ideas", difficulty: "easy", passage: "The bus was late this morning. ______, I arrived at school after the bell.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["However", "As a result", "For example", "Instead"], correct: 1, explanation: "The first sentence is a cause ('The bus was late'); the second is the effect ('I arrived at school after the bell'). Arriving late results from the late bus, so a cause-and-effect transition fits: 'As a result.' (A) 'However' signals contrast, but the two sentences agree. (C) 'For example' introduces an example, which the second sentence is not. (D) 'Instead' marks a replacement that does not apply. The answer is B." },
  { id: "t9rw2e-5", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "Yesterday we ______ a movie at the new theater downtown.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["watch", "watches", "watched", "watching"], correct: 2, explanation: "Verb tense: the time marker 'Yesterday' places the action in the past, so the verb must be the simple past 'watched.' (A) 'watch' is present tense. (B) 'watches' is present-tense third-person singular and also disagrees with 'we.' (D) 'watching' is a participle that cannot stand alone as the main verb without a helping verb. The answer is C." },
  { id: "t9rw2e-6", section: "rw", domain: "Craft and Structure", difficulty: "easy", passage: "The library was ______, so we could hear ourselves think.", prompt: "Which choice completes the text with the most logical word?", type: "mcq", choices: ["quiet", "loud", "crowded", "bright"], correct: 0, explanation: "The clause 'so we could hear ourselves think' describes a calm, silent space, so the blank means free of noise: 'quiet.' (B) 'loud' is the opposite and would make it hard to think. (C) 'crowded' describes how full a place is, not its noise level, and a crowd would not help you hear yourself think. (D) 'bright' describes light, which is unrelated to being able to think in silence. The answer is A." },
  { id: "t9rw2e-7", section: "rw", domain: "Information and Ideas", difficulty: "easy", passage: "Brushing your teeth twice a day removes food, prevents cavities, and keeps your breath fresh.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["Brushing teeth has several benefits.", "Brushing teeth causes cavities.", "Brushing teeth is unnecessary.", "Brushing only freshens breath."], correct: 0, explanation: "The text lists three good results of brushing: it 'removes food, prevents cavities, and keeps your breath fresh.' Choice A sums these up as 'several benefits.' (B) reverses the text, which says brushing 'prevents cavities,' not causes them. (C) contradicts the listed benefits. (D) is too narrow; fresh breath is only one of the three benefits named. The answer is A." },
  { id: "t9rw2e-8", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "She wore ______ orange scarf to the festival.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["a", "an", "the only", "some"], correct: 1, explanation: "Article rule: use 'an' before a word that begins with a vowel SOUND. 'Orange' starts with the vowel sound /o/, so 'an orange scarf' is correct. (A) 'a' is used before a consonant sound and would be 'a orange,' which sounds wrong. (C) 'the only' wrongly implies there is just one such scarf, which the sentence does not state. (D) 'some' is a plural-ish quantifier that clashes with the singular 'scarf.' The answer is B." },
  { id: "t9rw2e-9", section: "rw", domain: "Craft and Structure", difficulty: "easy", passage: "The runner was ______ after finishing the long race.", prompt: "Which choice completes the text with the most logical word?", type: "mcq", choices: ["exhausted", "energetic", "bored", "hungry"], correct: 0, explanation: "The phrase 'after finishing the long race' points to extreme tiredness, so the blank means worn out: 'exhausted.' (B) 'energetic' is the opposite of how one feels after a long race. (C) 'bored' does not follow from physical effort. (D) 'hungry' is possible in life but is not the effect the sentence sets up; the cause given is a long, tiring race, which logically yields exhaustion. The answer is A." },
  { id: "t9rw2e-10", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "The cat licked ______ paws after the meal.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["its", "it's", "their", "they're"], correct: 0, explanation: "Possessive vs. contraction: the blank shows ownership of the paws by the singular 'cat,' so the possessive pronoun 'its' (no apostrophe) is correct. (B) 'it's' is the contraction of 'it is' and would read 'it is paws,' which is nonsense. (C) 'their' is plural and disagrees with the singular 'cat.' (D) 'they're' means 'they are,' also plural and a contraction. The answer is A." },
  { id: "t9rw2e-11", section: "rw", domain: "Information and Ideas", difficulty: "med", passage: "The store offers free shipping on orders over $50; smaller orders pay a flat $5 fee.", prompt: "Which statement is best supported by the text?", type: "mcq", choices: ["A $20 order pays a $5 shipping fee.", "Every order ships for free.", "A $60 order pays $5 shipping.", "All orders pay $5 shipping."], correct: 0, explanation: "The text says free shipping applies 'on orders over $50' and that 'smaller orders pay a flat $5 fee.' A $20 order is under $50, so it is a 'smaller order' and pays the $5 fee - choice A. (B) is wrong because only orders over $50 ship free, not 'every order.' (C) is wrong: a $60 order is over $50 and ships free, not for $5. (D) is wrong because over-$50 orders pay nothing, so not 'all orders' pay $5. The answer is A." },
  { id: "t9rw2e-12", section: "rw", domain: "Expression of Ideas", difficulty: "easy", passage: "I wanted to learn guitar. ______, I signed up for weekly lessons.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["However", "So", "Otherwise", "In contrast"], correct: 1, explanation: "The first sentence is a cause ('I wanted to learn guitar'); the second is the action that follows ('I signed up for weekly lessons'). Signing up is the natural result of the wish, so a result transition fits: 'So.' (A) 'However' and (D) 'In contrast' signal opposition, but the two sentences agree. (C) 'Otherwise' means 'if not,' a hypothetical that does not apply. The answer is B." },
  { id: "t9rw2e-13", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "There ______ several books on the table this morning.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["was", "were", "is", "has been"], correct: 1, explanation: "In 'There ___ several books,' the word 'There' is not the subject; the true subject follows the verb and is the plural 'books.' The verb must agree with it and match the past time ('this morning'), so the plural past 'were' is correct. (A) 'was' is singular. (C) 'is' is singular and present tense. (D) 'has been' is singular present-perfect. The answer is B." },
  { id: "t9rw2e-14", section: "rw", domain: "Craft and Structure", difficulty: "easy", passage: "The new restaurant was very ______, with long lines out the door every night.", prompt: "Which choice completes the text with the most logical word?", type: "mcq", choices: ["popular", "empty", "expensive", "quiet"], correct: 0, explanation: "The detail 'long lines out the door every night' is evidence that many people want to eat there, so the blank means well-liked: 'popular.' (B) 'empty' contradicts the long lines. (C) 'expensive' is about price, which the lines do not indicate. (D) 'quiet' contradicts a busy restaurant with crowds every night. The answer is A." },
  { id: "t9rw2e-15", section: "rw", domain: "Information and Ideas", difficulty: "med", passage: "Owls hunt mainly at night, using sharp hearing and silent flight to surprise their prey.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["Owls are adapted for hunting at night.", "Owls hunt only in daylight.", "Owls cannot fly quietly.", "Owls have poor hearing."], correct: 0, explanation: "The text says owls 'hunt mainly at night, using sharp hearing and silent flight to surprise their prey.' These traits are tools for hunting in the dark, so the main idea is that owls are adapted for nighttime hunting - choice A. (B) contradicts 'mainly at night.' (C) contradicts 'silent flight.' (D) contradicts 'sharp hearing.' The answer is A." },
  { id: "t9rw2e-16", section: "rw", domain: "Expression of Ideas", difficulty: "med", passage: "The first batch of cookies burned. ______, we lowered the oven temperature for the second batch.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["Therefore", "However", "Meanwhile", "Likewise"], correct: 0, explanation: "The first sentence is a cause ('The first batch of cookies burned'); the second is the corrective response ('we lowered the oven temperature'). Lowering the heat is done because of the burning, so a result transition fits: 'Therefore.' (B) 'However' signals contrast, but the two sentences agree. (C) 'Meanwhile' marks simultaneity, not cause and effect. (D) 'Likewise' marks similarity, which does not apply. The answer is A." },
  { id: "t9rw2e-17", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "My brother and I ______ going to the concert together.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["is", "am", "are", "was"], correct: 2, explanation: "Subject-verb agreement: 'My brother and I' is a compound subject joined by 'and,' which makes it plural, so it takes the plural verb 'are.' (A) 'is' is singular. (B) 'am' is used only with 'I' alone, not with a compound subject. (D) 'was' is singular and past tense. The answer is C." },
  { id: "t9rw2e-18", section: "rw", domain: "Craft and Structure", difficulty: "easy", passage: "The directions were simple and ______, so no one got lost.", prompt: "Which choice completes the text with the most logical word?", type: "mcq", choices: ["clear", "confusing", "long", "secret"], correct: 0, explanation: "The result 'so no one got lost' shows the directions were easy to follow, so the blank means easy to understand: 'clear.' (B) 'confusing' is the opposite and would cause people to get lost. (C) 'long' describes length, not clarity, and would not by itself prevent confusion. (D) 'secret' makes no sense for directions meant to guide people. The answer is A." },
  { id: "t9rw2e-19", section: "rw", domain: "Information and Ideas", difficulty: "med", passage: "Recycling one ton of paper saves about 17 trees and a large amount of water and energy.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["Recycling paper conserves trees and other resources.", "Recycling paper wastes resources.", "Recycling paper has no benefits.", "Recycling paper requires cutting more trees."], correct: 0, explanation: "The text says recycling one ton of paper 'saves about 17 trees and a large amount of water and energy.' Saving trees, water, and energy is conserving resources, which is choice A. (B) reverses the text, which describes saving, not wasting. (C) contradicts the benefits stated. (D) is the opposite of saving trees; recycling reduces the need to cut them. The answer is A." },
  { id: "t9rw2e-20", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "He packed his bag, locked the door, and ______ for the airport.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["leaving", "left", "to leave", "leaves"], correct: 1, explanation: "Parallel structure: items in a series must share the same grammatical form. The sentence lists 'packed his bag, locked the door, and ______' - two simple past-tense verbs, so the third must match: 'left.' (A) 'leaving' is a participle, breaking the parallel. (C) 'to leave' is an infinitive, also nonparallel. (D) 'leaves' is present tense and clashes with the past 'packed' and 'locked.' The answer is B." },
  { id: "t9rw2e-21", section: "rw", domain: "Expression of Ideas", difficulty: "med", passage: "The garden needed more sun. ______, we moved the planters to the south side of the yard.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["Nevertheless", "So", "However", "Instead"], correct: 1, explanation: "The first sentence is a cause ('The garden needed more sun'); the second is the action taken in response ('we moved the planters to the south side'). Moving the planters follows from needing sun, so a result transition fits: 'So.' (A) 'Nevertheless' and (C) 'However' signal contrast, but the two sentences agree. (D) 'Instead' marks a replacement that does not apply. The answer is B." },
  { id: "t9rw2e-22", section: "rw", domain: "Craft and Structure", difficulty: "med", passage: "The coach's praise was ______, never given unless it was truly earned.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["sparing", "constant", "empty", "loud"], correct: 0, explanation: "The clause 'never given unless it was truly earned' shows the coach gave praise rarely and only when deserved, so the blank means held back: 'sparing.' (B) 'constant' is the opposite of rarely given. (C) 'empty' means insincere, but praise given only when earned is genuine. (D) 'loud' describes volume, not how often or selectively it was given. The answer is A." },
  { id: "t9rw2e-23", section: "rw", domain: "Information and Ideas", difficulty: "med", passage: "All members may borrow up to five books; first-year members may borrow only three.", prompt: "Which statement is best supported by the text?", type: "mcq", choices: ["A second-year member may borrow up to five books.", "First-year members may borrow ten books.", "No members may borrow any books.", "Every member may borrow only three books."], correct: 0, explanation: "The text says 'All members may borrow up to five books' but 'first-year members may borrow only three.' A second-year member is not a first-year, so the general five-book limit applies - choice A. (B) is wrong: first-years are capped at three, not ten. (C) contradicts the borrowing allowances. (D) is wrong because only first-years are limited to three; other members may borrow five. The answer is A." },
  { id: "t9rw2e-24", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "The chef chopped the onions ______ then added them to the sizzling pan.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["onions, and", "onions and", "onions; and", "onions: and"], correct: 0, explanation: "Punctuation: among the four options, 'onions, and' is the only correct one. A semicolon (C) and a colon (D) must each be preceded AND followed by structures they are licensed to join - a semicolon needs an independent clause on the right, and a colon needs an introductory independent clause; neither condition is met by 'and then added them ...', so both are wrong. Between the two comma-free and comma options, the comma before 'and then' correctly marks the pause and keeps the sequence clear, whereas (B) 'onions and' runs the elements together. The answer is A." },
  { id: "t9rw2e-25", section: "rw", domain: "Craft and Structure", difficulty: "med", passage: "The lecture was ______, packing a semester's worth of ideas into a single hour.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["dense", "shallow", "rambling", "empty"], correct: 0, explanation: "The phrase 'packing a semester's worth of ideas into a single hour' shows the lecture was tightly filled with content, so the blank means full of substance: 'dense.' (B) 'shallow' is the opposite of packed with ideas. (C) 'rambling' means wandering and unfocused, contradicting a tightly packed hour. (D) 'empty' is the opposite of full of ideas. The answer is A." },
  { id: "t9rw2e-26", section: "rw", domain: "Information and Ideas", difficulty: "med", passage: "The article first describes the problem of plastic waste, then surveys three proposed solutions in turn.", prompt: "Which choice best describes the structure of the text?", type: "mcq", choices: ["A problem is stated and then possible solutions are reviewed.", "A single solution is rejected outright.", "Only the history of plastic is told.", "Two unrelated topics are compared."], correct: 0, explanation: "The text says the article 'first describes the problem of plastic waste, then surveys three proposed solutions in turn.' That is a problem-then-solutions structure, exactly choice A. (B) is wrong: solutions are surveyed, not a single one 'rejected outright.' (C) is wrong because the focus is the problem and solutions, not 'the history of plastic.' (D) is wrong because the two parts (problem and its solutions) are related, not 'two unrelated topics.' The answer is A." },
  { id: "t9rw2e-27", section: "rw", domain: "Expression of Ideas", difficulty: "med", passage: "Ticket sales were strong all summer. ______, the festival earned enough to fund next year's event.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["However", "As a result", "Otherwise", "In contrast"], correct: 1, explanation: "The first sentence is a cause ('Ticket sales were strong all summer'); the second is the effect ('the festival earned enough to fund next year's event'). The earnings follow from the strong sales, so a cause-and-effect transition fits: 'As a result.' (A) 'However' and (D) 'In contrast' signal opposition, but the two sentences agree. (C) 'Otherwise' means 'if not,' a hypothetical that does not apply. The answer is B." },
];

// ─────────────────────────── R&W MODULE 2 HARD (med/hard, 27) ───────────────────────────
const T9_RW_M2H: SatQuestion[] = [
  { id: "t9rw2h-1", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "The memoir is admirably ______: the author refuses to flatter herself, dwelling as readily on her failures as on her triumphs.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["candid", "evasive", "boastful", "guarded"], correct: 0, explanation: "The colon explains the blank: 'the author refuses to flatter herself, dwelling as readily on her failures as on her triumphs.' That is frank, honest self-portrayal, so the blank means open and truthful: 'candid.' (B) 'evasive' means dodging the truth, the opposite of refusing to flatter herself. (C) 'boastful' contradicts dwelling on failures. (D) 'guarded' means cautious and withholding, the opposite of writing openly about one's failures. The answer is A." },
  { id: "t9rw2h-2", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "The essay opens with a sweeping generalization, then devotes its remaining pages to the exceptions that complicate it.", prompt: "Which choice best describes the function of the opening generalization?", type: "mcq", choices: ["It sets up a claim the essay then qualifies with exceptions.", "It states the essay's settled conclusion.", "It lists technical definitions.", "It ends the essay's argument."], correct: 0, explanation: "The text says the essay 'opens with a sweeping generalization, then devotes its remaining pages to the exceptions that complicate it.' The opening generalization therefore sets up a claim that the essay then qualifies with exceptions - choice A. (B) is wrong: a claim later complicated by exceptions is not a 'settled conclusion.' (C) is unsupported; a generalization is not a list of 'technical definitions.' (D) is wrong because the generalization opens the essay rather than ending its argument. The answer is A." },
  { id: "t9rw2h-3", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "A reservoir held 120 million liters in spring, 95 million in early summer, and 92 million by late summer.", prompt: "Which statement is best supported by the data?", type: "mcq", choices: ["The sharpest drop occurred between spring and early summer.", "The reservoir gained water over the period.", "Late summer saw the steepest decline.", "The level stayed constant all year."], correct: 0, explanation: "Compare the two changes. Spring to early summer: 120 − 95 = 25 million liters lost. Early to late summer: 95 − 92 = 3 million liters lost. Since 25 > 3, the sharpest drop occurred between spring and early summer - choice A. (B) is wrong: the level fell (120 → 92), it did not gain. (C) is wrong because late summer's 3-million drop is the smallest, not the steepest. (D) is wrong because the level changed each period. The answer is A." },
  { id: "t9rw2h-4", section: "rw", domain: "Expression of Ideas", difficulty: "hard", passage: "The treaty is widely admired for its idealism. ______, it lacks any mechanism to enforce the obligations it so eloquently describes.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["Therefore", "Yet", "Likewise", "Accordingly"], correct: 1, explanation: "The first sentence praises the treaty ('widely admired for its idealism'); the second names a serious flaw ('lacks any mechanism to enforce' its obligations). Praise followed by a contradicting weakness calls for a contrast transition: 'Yet.' (A) 'Therefore,' (C) 'Likewise,' and (D) 'Accordingly' all signal agreement or result, but the flaw cuts against the admiration rather than following from it. The answer is B." },
  { id: "t9rw2h-5", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "The internship trains participants to gather data carefully, to interpret it rigorously, and ______ it clearly.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["to present", "presenting", "present", "presented"], correct: 0, explanation: "Parallel structure: the series uses matching infinitive phrases - 'to gather data carefully, to interpret it rigorously, and ______ it clearly.' The third item must also be an infinitive: 'to present.' (B) 'presenting' is a participle, breaking the parallel. (C) 'present' drops the 'to' that the other two items carry. (D) 'presented' is past tense and nonparallel. The answer is A." },
  { id: "t9rw2h-6", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "Her prose is ______, every clause stripped of anything that does not earn its place.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["spare", "ornate", "rambling", "verbose"], correct: 0, explanation: "The clause 'every clause stripped of anything that does not earn its place' describes lean, pared-down writing, so the blank means minimal: 'spare.' (B) 'ornate' means heavily decorated, the opposite of stripped down. (C) 'rambling' means wandering and wordy, contradicting prose with nothing extra. (D) 'verbose' means using too many words, also the opposite of stripped-down prose. The answer is A." },
  { id: "t9rw2h-7", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "Whereas the first biographer accepted the legend uncritically, the second tests each anecdote against surviving letters and records.", prompt: "Which choice best describes the main purpose of the text?", type: "mcq", choices: ["To contrast two biographers' approaches to evidence.", "To argue that legends are reliable history.", "To summarize only the first biography.", "To praise the legend as fact."], correct: 0, explanation: "The sentence is built on 'Whereas the first biographer accepted the legend uncritically, the second tests each anecdote against surviving letters and records.' 'Whereas' marks a contrast, and the two halves compare how each biographer handles evidence - choice A. (B) is wrong: the text favors testing over accepting legend, not calling legends 'reliable history.' (C) is wrong because both biographers are discussed. (D) reverses the point; the second biographer questions the legend rather than praising it as fact. The answer is A." },
  { id: "t9rw2h-8", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "Neither the manager nor her assistants ______ aware that the shipment had already arrived.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["was", "were", "is", "has been"], correct: 1, explanation: "Agreement with 'neither ... nor': when subjects are joined by 'neither ... nor,' the verb agrees with the subject NEARER to it. Here the nearer subject is the plural 'assistants,' so the verb is plural: 'were.' (A) 'was' and (C) 'is' are singular, agreeing wrongly with 'manager' rather than the nearer 'assistants.' (D) 'has been' is also singular. The answer is B." },
  { id: "t9rw2h-9", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "The general's strategy was ______: each apparent retreat was, in fact, a calculated step toward a larger encirclement.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["cunning", "haphazard", "transparent", "reckless"], correct: 0, explanation: "The colon explains the blank: 'each apparent retreat was, in fact, a calculated step toward a larger encirclement.' Disguising real intentions to trap the enemy is clever and crafty, so the blank means shrewd: 'cunning.' (B) 'haphazard' means random and unplanned, the opposite of a calculated scheme. (C) 'transparent' means easy to see through, but the strategy's point was that the retreats hid its true aim. (D) 'reckless' means careless of risk, contradicting a carefully calculated plan. The answer is A." },
  { id: "t9rw2h-10", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "In a trial, plants given the new nutrient grew 40 percent taller than untreated plants, but they also flowered two weeks later.", prompt: "Which statement is best supported by the text?", type: "mcq", choices: ["The nutrient increased height but delayed flowering.", "The nutrient had no measurable effect.", "Treated plants flowered earlier.", "Treated plants were shorter."], correct: 0, explanation: "The text reports two effects: treated plants 'grew 40 percent taller' (a height increase) 'but they also flowered two weeks later' (a delay in flowering). Choice A captures both: increased height, delayed flowering. (B) is wrong because there were clear measurable effects. (C) reverses the timing: they flowered later, not earlier. (D) reverses the height: they were taller, not shorter. The answer is A." },
  { id: "t9rw2h-11", section: "rw", domain: "Expression of Ideas", difficulty: "hard", passage: "The algorithm sorts millions of records in seconds. ______, it stumbles on the small, irregular datasets that humans handle with ease.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["Hence", "Paradoxically", "Therefore", "Consequently"], correct: 1, explanation: "The first sentence shows great strength ('sorts millions of records in seconds'); the second shows a surprising weakness ('stumbles on the small, irregular datasets that humans handle with ease'). That a tool brilliant at the huge fails at the simple is a seeming contradiction, so 'Paradoxically' fits. (A) 'Hence,' (C) 'Therefore,' and (D) 'Consequently' all signal a result, but the weakness does not follow as a consequence of the strength; it cuts against it. The answer is B." },
  { id: "t9rw2h-12", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "The expedition reached the summit at dawn ______ a feat no team had managed in the storm-plagued season.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["dawn,", "dawn;", "dawn:", "dawn"], correct: 0, explanation: "Punctuation: 'a feat no team had managed ...' is an appositive that renames and describes the whole preceding idea (reaching the summit at dawn). A single comma correctly attaches this nonessential descriptive phrase to the main clause. (B) a semicolon must join two independent clauses, but 'a feat ...' is a phrase, not a clause. (C) a colon would also need to be preceded by an independent clause and to introduce a list or explanation in clause form; here the comma is the standard appositive mark. (D) no punctuation fuses the appositive to the clause, creating confusion. The answer is A." },
  { id: "t9rw2h-13", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "Far from being ______, the committee's silence was a deliberate tactic meant to pressure the other side into speaking first.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["passive", "strategic", "calculated", "intentional"], correct: 0, explanation: "The frame 'Far from being ______, the silence was a deliberate tactic' demands a word that contrasts with 'deliberate.' Silence that is NOT passive but instead purposeful needs 'passive' (inactive, unintentional) in the blank, which the sentence then denies. (B) 'strategic,' (C) 'calculated,' and (D) 'intentional' are all near-synonyms of 'deliberate'; placing any of them in the blank would have the sentence say the silence was 'far from deliberate ... a deliberate tactic,' a contradiction. The answer is A." },
  { id: "t9rw2h-14", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "The author concedes that her data are limited, then argues that even this partial evidence points unmistakably in one direction.", prompt: "Which choice best describes the function of the concession?", type: "mcq", choices: ["It acknowledges a weakness before arguing the evidence still holds.", "It abandons the argument entirely.", "It introduces an unrelated topic.", "It restates the opposing thesis approvingly."], correct: 0, explanation: "The text says the author 'concedes that her data are limited, then argues that even this partial evidence points unmistakably in one direction.' The concession admits a weakness before she presses her case anyway - choice A. (B) is wrong: she does not abandon the argument; she continues it. (C) is wrong because the concession is about her own data, not an unrelated topic. (D) is wrong because she does not approvingly restate an opposing thesis; she grants a limit in her own evidence. The answer is A." },
  { id: "t9rw2h-15", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "The committee reviewed the proposal, revised its budget, and ______ it to the board for final approval.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["submitting", "submitted", "to submit", "submits"], correct: 1, explanation: "Parallel structure: the series lists 'reviewed the proposal, revised its budget, and ______ it to the board' - two simple past-tense verbs, so the third must match: 'submitted.' (A) 'submitting' is a participle, breaking the parallel. (C) 'to submit' is an infinitive, also nonparallel. (D) 'submits' is present tense and clashes with the past 'reviewed' and 'revised.' The answer is B." },
  { id: "t9rw2h-16", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "The painting's appeal is ______: at first it seems merely pretty, but each viewing reveals deeper layers of meaning.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["cumulative", "instantaneous", "fleeting", "superficial"], correct: 0, explanation: "The colon explains the blank: 'at first it seems merely pretty, but each viewing reveals deeper layers of meaning.' Appeal that grows and builds with repeated viewing is 'cumulative' (increasing by successive additions). (B) 'instantaneous' means all-at-once, contradicting appeal that deepens over time. (C) 'fleeting' means quickly fading, the opposite of growing. (D) 'superficial' means shallow, contradicting 'deeper layers of meaning.' The answer is A." },
  { id: "t9rw2h-17", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "Of three coatings tested, the first lasted 4 years, the second 11 years, and the third 12 years before failing.", prompt: "Which statement is best supported by the data?", type: "mcq", choices: ["The jump in durability was far greater from the first to the second coating than from the second to the third.", "All three coatings lasted the same time.", "The first coating lasted longest.", "The third coating failed first."], correct: 0, explanation: "Compare the gains in durability. First to second coating: 11 − 4 = 7 years more. Second to third: 12 − 11 = 1 year more. Since 7 > 1, the jump from first to second is far greater than from second to third - choice A. (B) is wrong: the three lifespans (4, 11, 12) differ. (C) is wrong because the first lasted the shortest, not longest. (D) is wrong because the first coating failed first (at 4 years), not the third. The answer is A." },
  { id: "t9rw2h-18", section: "rw", domain: "Expression of Ideas", difficulty: "hard", passage: "The reforms reduced waiting times dramatically. ______, patient satisfaction scores barely moved, suggesting that speed was not the chief concern.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["Accordingly", "However", "Therefore", "Hence"], correct: 1, explanation: "The first sentence reports a big improvement ('reduced waiting times dramatically'); the second reports an unexpected non-result ('satisfaction scores barely moved'). You would expect faster service to lift satisfaction, so the flat scores defy expectation, calling for a contrast transition: 'However.' (A) 'Accordingly,' (C) 'Therefore,' and (D) 'Hence' all signal a result, but the unchanged satisfaction is the opposite of what the reform would predict. The answer is B." },
  { id: "t9rw2h-19", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "The bridge, which engineers had declared sound only months earlier ______ closed for emergency repairs.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["earlier, was", "earlier was", "earlier; was", "earlier: was"], correct: 0, explanation: "Punctuation: 'which engineers had declared sound only months earlier' is a nonrestrictive relative clause that interrupts the sentence. Such a clause is set off by a pair of commas - one before 'which' (already present) and one after 'earlier' to close it before the main verb 'was.' So 'earlier, was' is correct. (B) 'earlier was' omits the needed closing comma. (C) a semicolon would wrongly break the sentence, leaving 'was closed for emergency repairs' without a subject. (D) a colon cannot close an interrupting clause. The answer is A." },
  { id: "t9rw2h-20", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "His arguments were so ______ that opponents struggled to find any opening through which to attack them.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["airtight", "porous", "flimsy", "tentative"], correct: 0, explanation: "The clause 'opponents struggled to find any opening through which to attack them' shows arguments with no weak points, so the blank means flawless and unassailable: 'airtight.' (B) 'porous' means full of holes, which would give opponents many openings. (C) 'flimsy' means weak and easily broken, the opposite of leaving no opening. (D) 'tentative' means hesitant and unsure, which would invite attack rather than resist it. The answer is A." },
  { id: "t9rw2h-21", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "Rather than treating folklore as mere entertainment, the scholar reads each tale as a coded record of the community's deepest anxieties.", prompt: "Which choice best describes the scholar's approach?", type: "mcq", choices: ["She interprets folktales as evidence of a community's underlying fears.", "She dismisses folktales as meaningless.", "She studies only modern entertainment.", "She argues folktales have no cultural value."], correct: 0, explanation: "The text says that 'rather than treating folklore as mere entertainment, the scholar reads each tale as a coded record of the community's deepest anxieties.' So she interprets folktales as evidence of a community's underlying fears - choice A. (B) is the opposite; she finds deep meaning, not meaninglessness. (C) is wrong because she studies folklore, not 'only modern entertainment.' (D) contradicts her view that tales carry cultural meaning. The answer is A." },
  { id: "t9rw2h-22", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "The data, collected over a decade by dozens of volunteers, ______ finally ready for analysis.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["were", "was", "is", "being"], correct: 0, explanation: "Subject-verb agreement: in formal Standard English the subject 'data' is treated as plural (the plural of 'datum'), so it takes the plural verb 'were.' The long interrupting phrase 'collected over a decade by dozens of volunteers' sits between subject and verb to distract you, but it does not change the subject. (B) 'was' and (C) 'is' are singular. (D) 'being' is a participle that cannot serve as the main verb. The answer is A." },
  { id: "t9rw2h-23", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "The biography is ______, refusing to settle on a single verdict and leaving its subject as contradictory as he was in life.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["unresolved", "conclusive", "simplistic", "one-sided"], correct: 0, explanation: "The clause 'refusing to settle on a single verdict and leaving its subject as contradictory as he was in life' shows a biography that reaches no final judgment, so the blank means left open: 'unresolved.' (B) 'conclusive' means settling the matter, the opposite of refusing a verdict. (C) 'simplistic' means oversimplified, but keeping the subject contradictory is the opposite of simplifying. (D) 'one-sided' means slanted to a single view, contradicting a portrait that preserves contradiction. The answer is A." },
  { id: "t9rw2h-24", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "The paper argues that the famine, long blamed on drought alone, was driven equally by trade policies that drained local grain reserves.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["The famine had a political cause alongside the drought.", "Drought alone fully explains the famine.", "Trade policy prevented the famine.", "The famine never actually occurred."], correct: 0, explanation: "The text says the famine, 'long blamed on drought alone, was driven equally by trade policies that drained local grain reserves.' Trade policy is a human/political cause set equal to the drought, so the main idea is that the famine had a political cause alongside the drought - choice A. (B) contradicts 'driven equally by trade policies,' which says drought alone is not the full story. (C) reverses the text: trade policy worsened the famine, it did not prevent it. (D) is false; the famine is treated as real. The answer is A." },
  { id: "t9rw2h-25", section: "rw", domain: "Expression of Ideas", difficulty: "hard", passage: "The instrument can detect a single photon. ______, it must be cooled to near absolute zero, which makes it costly to operate.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["Likewise", "To achieve this", "Nevertheless", "In contrast"], correct: 1, explanation: "The first sentence states a capability ('detect a single photon'); the second states what that capability requires ('it must be cooled to near absolute zero'). The cooling is the means of achieving the detection, so a transition pointing to that purpose fits: 'To achieve this.' (A) 'Likewise' marks similarity, which does not apply. (C) 'Nevertheless' and (D) 'In contrast' signal opposition, but the two sentences are not opposed; the second explains how the first is made possible. The answer is B." },
  { id: "t9rw2h-26", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "Drawn by tales of gold ______ prospectors flooded the valley within a single year.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["gold,", "gold;", "gold:", "gold"], correct: 0, explanation: "Punctuation: 'Drawn by tales of gold' is an introductory participial phrase modifying 'prospectors.' An introductory modifier is followed by a comma to separate it from the main clause, so 'gold,' is correct. (B) a semicolon must join two independent clauses, but the introductory phrase is not a clause. (C) a colon needs an introducing independent clause before it, which this phrase is not. (D) no punctuation leaves the modifier improperly fused to the clause. The answer is A." },
  { id: "t9rw2h-27", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "The verdict was ______: while it cleared the defendant of the gravest charge, it left a cloud of lesser suspicions intact.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["equivocal", "decisive", "unanimous", "absolute"], correct: 0, explanation: "The colon explains the blank: the verdict 'cleared the defendant of the gravest charge' but 'left a cloud of lesser suspicions intact.' A verdict that points two ways at once is 'equivocal' (ambiguous, open to more than one interpretation). (B) 'decisive' means clear-cut, the opposite of leaving suspicions intact. (C) 'unanimous' describes agreement among voters, not the mixed nature of the outcome. (D) 'absolute' means complete and unqualified, contradicting a verdict that settled only part of the matter. The answer is A." },
];

// ─────────────────────────── MATH MODULE 1 (mixed, 22) ───────────────────────────
const T9_M_M1: SatQuestion[] = [
  { id: "t9m1-1", section: "math", domain: "Algebra", difficulty: "easy", prompt: "If 7x − 4 = 31, what is the value of x?", type: "grid", gridAnswers: ["5"], explanation: "Goal: solve 7x − 4 = 31 for x. Add 4 to both sides: 7x − 4 + 4 = 31 + 4, so 7x = 35. Divide both sides by 7: x = 35/7 = 5. Check: 7(5) − 4 = 35 − 4 = 31, which matches. A common trap is dividing before adding the 4, which would give the wrong value. The answer is 5." },
  { id: "t9m1-2", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "easy", prompt: "A recipe makes 36 cookies and serves 9 people equally. How many cookies does each person get?", type: "mcq", choices: ["4", "6", "9", "27"], correct: 0, explanation: "Goal: split 36 cookies equally among 9 people. Divide the total by the number of people: 36 ÷ 9 = 4 cookies each. Check: 4 cookies × 9 people = 36 cookies, the full batch. (B) 6 comes from 36 ÷ 6, the wrong divisor. (C) 9 just repeats the number of people. (D) 27 is 36 − 9, mistakenly subtracting instead of dividing. The answer is A (4)." },
  { id: "t9m1-3", section: "math", domain: "Advanced Math", difficulty: "med", prompt: "If f(x) = x² − 5, what is the value of f(4)?", type: "mcq", choices: ["11", "3", "21", "16"], correct: 0, explanation: "Goal: evaluate f(x) = x^2 − 5 at x = 4. Substitute 4 for x: f(4) = 4^2 − 5. Square first: 4^2 = 16. Then subtract: 16 − 5 = 11. (B) 3 comes from 4^2 = 8 (doubling instead of squaring): 8 − 5 = 3. (C) 21 comes from 16 + 5, adding instead of subtracting. (D) 16 forgets to subtract the 5. The answer is A (11)." },
  { id: "t9m1-4", section: "math", domain: "Geometry and Trigonometry", difficulty: "easy", prompt: "A square has an area of 81 square units. What is the length of one side?", type: "grid", gridAnswers: ["9"], explanation: "Goal: find a square's side length from its area. A square's area is side^2, so side^2 = 81. Take the positive square root: side = √81 = 9. Check: 9^2 = 81, the given area. A trap is dividing 81 by 4 (confusing it with perimeter) to get 20.25, which is wrong. The answer is 9." },
  { id: "t9m1-5", section: "math", domain: "Algebra", difficulty: "med", prompt: "The equation y = 3x + 2 is graphed in the xy-plane. What is the y-intercept of the line?", type: "mcq", choices: ["2", "3", "0", "5"], correct: 0, explanation: "Goal: find the y-intercept of y = 3x + 2. A line in slope-intercept form y = mx + b crosses the y-axis at b, the constant term. Here b = 2, so the y-intercept is 2 (the point (0, 2)). Check: set x = 0, giving y = 3(0) + 2 = 2. (B) 3 is the slope m, not the intercept - the classic trap. (C) 0 would require the line to pass through the origin, but the constant is 2. (D) 5 adds 3 + 2 with no basis. The answer is A (2)." },
  { id: "t9m1-6", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "med", prompt: "A shirt originally priced at $40 is on sale for $34. By what percent was the price reduced?", type: "mcq", choices: ["15%", "6%", "10%", "20%"], correct: 0, explanation: "Goal: find the percent reduction from $40 to $34. The dollar discount is 40 − 34 = 6. Percent reduction = discount ÷ original price = 6 ÷ 40 = 0.15 = 15%. Check: 15% of 40 is 0.15 × 40 = 6, which gives 40 − 6 = 34. (B) 6% mistakes the dollar amount ($6) for a percent. (C) 10% comes from 4/40, using the wrong difference. (D) 20% comes from 8/40. The answer is A (15%)." },
  { id: "t9m1-7", section: "math", domain: "Algebra", difficulty: "med", prompt: "If 4(x + 3) = 32, what is the value of x?", type: "grid", gridAnswers: ["5"], explanation: "Goal: solve 4(x + 3) = 32 for x. Divide both sides by 4: x + 3 = 32/4 = 8. Subtract 3 from both sides: x = 8 − 3 = 5. (You could also distribute first: 4x + 12 = 32, then 4x = 20, x = 5.) Check: 4(5 + 3) = 4(8) = 32, which matches. A trap is subtracting 3 before dividing, giving the wrong value. The answer is 5." },
  { id: "t9m1-8", section: "math", domain: "Advanced Math", difficulty: "med", prompt: "What is the sum of the solutions to x² − 7x + 12 = 0?", type: "mcq", choices: ["7", "12", "-7", "5"], correct: 0, explanation: "Goal: find the sum of the solutions of x^2 − 7x + 12 = 0. Factor: find two numbers that multiply to 12 and add to −7, namely −3 and −4, so (x − 3)(x − 4) = 0. The roots are x = 3 and x = 4, and their sum is 3 + 4 = 7. (Shortcut: for x^2 + bx + c, the sum of roots is −b = 7.) Check: 3 + 4 = 7 and 3 × 4 = 12, matching the equation. (B) 12 is the product of the roots, not the sum. (C) −7 is −b read with the wrong sign. (D) 5 has no basis. The answer is A (7)." },
  { id: "t9m1-9", section: "math", domain: "Geometry and Trigonometry", difficulty: "med", prompt: "A circle has a radius of 5. What is its area? (Use π in the answer.)", type: "mcq", choices: ["25π", "10π", "5π", "50π"], correct: 0, explanation: "Goal: find the area of a circle with radius 5. The area formula is A = πr^2. Substitute r = 5: A = π(5^2) = π(25) = 25π. (B) 10π is the circumference (2πr = 10π), not the area - the most common trap. (C) 5π forgets to square the radius. (D) 50π comes from doubling 25π or from π(5)(2)(5) errors. The answer is A (25π)." },
  { id: "t9m1-10", section: "math", domain: "Algebra", difficulty: "med", prompt: "A line passes through (0, 1) and (2, 7). What is its slope?", type: "grid", gridAnswers: ["3"], explanation: "Goal: find the slope of the line through (0, 1) and (2, 7). Slope = (change in y)/(change in x) = (y2 − y1)/(x2 − x1). Substitute: (7 − 1)/(2 − 0) = 6/2 = 3. Check: starting at (0, 1) and rising 3 per step in x, at x = 2 the y-value is 1 + 3(2) = 7, matching the second point. A trap is inverting the formula to (x2 − x1)/(y2 − y1) = 2/6, which is wrong. The answer is 3." },
  { id: "t9m1-11", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "med", prompt: "The mean of 4, 8, 10, and x is 8. What is the value of x?", type: "grid", gridAnswers: ["10"], explanation: "Goal: find x given that the mean of 4, 8, 10, and x is 8. Mean = sum ÷ count, so (4 + 8 + 10 + x)/4 = 8. Multiply both sides by 4: 4 + 8 + 10 + x = 32. The known three sum to 22, so 22 + x = 32, giving x = 32 − 22 = 10. Check: (4 + 8 + 10 + 10)/4 = 32/4 = 8, which matches. A trap is dividing 8 by 4 or forgetting to multiply the mean by the count first. The answer is 10." },
  { id: "t9m1-12", section: "math", domain: "Algebra", difficulty: "med", prompt: "If 2x + 3y = 18 and y = 2, what is the value of x?", type: "mcq", choices: ["6", "9", "3", "12"], correct: 0, explanation: "Goal: solve 2x + 3y = 18 with y = 2. Substitute y = 2: 2x + 3(2) = 18, so 2x + 6 = 18. Subtract 6: 2x = 12. Divide by 2: x = 6. Check: 2(6) + 3(2) = 12 + 6 = 18, which matches. (B) 9 comes from ignoring the 3y term and doing 18/2. (C) 3 comes from solving 2x = 6. (D) 12 stops at 2x = 12 without dividing. The answer is A (6)." },
  { id: "t9m1-13", section: "math", domain: "Advanced Math", difficulty: "med", prompt: "If 3^x = 81, what is the value of x?", type: "grid", gridAnswers: ["4"], explanation: "Goal: solve 3^x = 81. Rewrite 81 as a power of 3: 3^1 = 3, 3^2 = 9, 3^3 = 27, 3^4 = 81. So 3^x = 3^4, and with equal bases the exponents are equal: x = 4. Check: 3^4 = 81, which matches. A trap is dividing 81 by 3 to get 27 and answering 27, or treating the exponent as 81/3. The answer is 4." },
  { id: "t9m1-14", section: "math", domain: "Geometry and Trigonometry", difficulty: "med", prompt: "Two angles of a triangle measure 50° and 65°. What is the measure, in degrees, of the third angle?", type: "grid", gridAnswers: ["65"], explanation: "Goal: find the third angle of a triangle with angles 50° and 65°. The angles of any triangle sum to 180°, so the third angle = 180 − 50 − 65. Compute step by step: 180 − 50 = 130, then 130 − 65 = 65. So the third angle is 65°. Check: 50 + 65 + 65 = 180, which confirms it. A trap is using 360° (the sum for a quadrilateral) instead of 180°. The answer is 65." },
  { id: "t9m1-15", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "med", prompt: "A map uses a scale of 1 cm to 8 km. Two cities are 5 cm apart on the map. How many kilometers apart are they?", type: "mcq", choices: ["40", "13", "32", "45"], correct: 0, explanation: "Goal: convert 5 cm on the map to real kilometers using the scale 1 cm = 8 km. Multiply the map distance by the scale: 5 cm × 8 km/cm = 40 km. Check: each centimeter is 8 km, so 5 of them is 5 × 8 = 40 km. (B) 13 comes from adding 5 + 8. (C) 32 comes from 4 × 8, using the wrong map distance. (D) 45 comes from 5 × 9. The answer is A (40)." },
  { id: "t9m1-16", section: "math", domain: "Algebra", difficulty: "med", prompt: "If 5x + 2 ≤ 17, what is the greatest integer value of x?", type: "mcq", choices: ["3", "2", "4", "5"], correct: 0, explanation: "Goal: find the greatest integer x with 5x + 2 ≤ 17. Subtract 2 from both sides: 5x ≤ 15. Divide both sides by 5 (positive, so the inequality direction stays): x ≤ 3. The greatest integer satisfying x ≤ 3 is 3 itself. Check: 5(3) + 2 = 17 ≤ 17, true; x = 4 gives 22 > 17, too big. (B) 2 is valid but not the greatest. (C) 4 and (D) 5 violate the inequality. The answer is A (3)." },
  { id: "t9m1-17", section: "math", domain: "Advanced Math", difficulty: "med", prompt: "If (x − 2)² = 49 and x > 0, what is the value of x?", type: "mcq", choices: ["9", "7", "5", "47"], correct: 0, explanation: "Goal: solve (x − 2)^2 = 49 with x > 0. Take the square root of both sides, remembering both signs: x − 2 = ±7. That gives two cases: x − 2 = 7 → x = 9, or x − 2 = −7 → x = −5. Since x > 0, keep x = 9. Check: (9 − 2)^2 = 7^2 = 49, which matches. (B) 7 forgets to add back the 2. (C) 5 is the absolute value of the rejected root. (D) 47 comes from 49 − 2, mishandling the square. The answer is A (9)." },
  { id: "t9m1-18", section: "math", domain: "Geometry and Trigonometry", difficulty: "med", prompt: "A right triangle has legs of length 9 and 12. What is the length of the hypotenuse?", type: "grid", gridAnswers: ["15"], explanation: "Goal: find the hypotenuse of a right triangle with legs 9 and 12. Use the Pythagorean theorem c^2 = a^2 + b^2: c^2 = 9^2 + 12^2 = 81 + 144 = 225. Take the square root: c = √225 = 15. Check: 9^2 + 12^2 = 81 + 144 = 225 = 15^2 (this is a 3-4-5 triple scaled by 3). A trap is adding the legs (9 + 12 = 21) instead of using the theorem. The answer is 15." },
  { id: "t9m1-19", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "med", prompt: "A jar holds 6 red, 4 blue, and 10 green marbles. If one is drawn at random, what is the probability it is blue?", type: "mcq", choices: ["1/5", "4/10", "1/4", "1/6"], correct: 0, explanation: "Goal: find the probability of drawing a blue marble. First find the total: 6 red + 4 blue + 10 green = 20 marbles. Probability = favorable ÷ total = 4 blue / 20 = 4/20 = 1/5. Check: 1/5 of 20 is 4, the number of blue marbles. (B) 4/10 uses the wrong total (10 instead of 20). (C) 1/4 comes from 5/20 or miscounting blue. (D) 1/6 uses the red count, not blue. The answer is A (1/5)." },
  { id: "t9m1-20", section: "math", domain: "Algebra", difficulty: "hard", prompt: "If 3x − 2y = 12 and 3x + 2y = 24, what is the value of x?", type: "mcq", choices: ["6", "4", "3", "8"], correct: 0, explanation: "Goal: solve the system 3x − 2y = 12 and 3x + 2y = 24 for x. Add the two equations so the y-terms cancel: (3x − 2y) + (3x + 2y) = 12 + 24, giving 6x = 36. Divide by 6: x = 6. Check: with x = 6, the second equation gives 18 + 2y = 24, so y = 3; then 3(6) − 2(3) = 18 − 6 = 12, matching the first. (B) 4, (C) 3, and (D) 8 do not satisfy 6x = 36. The answer is A (6)." },
  { id: "t9m1-21", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "The function h(x) = 2x² + 1 is defined for all real x. What is the value of h(−3)?", type: "mcq", choices: ["19", "37", "13", "-17"], correct: 0, explanation: "Goal: evaluate h(x) = 2x^2 + 1 at x = −3. Substitute: h(−3) = 2(−3)^2 + 1. Square first (a negative squared is positive): (−3)^2 = 9. Multiply: 2 × 9 = 18. Add 1: 18 + 1 = 19. (B) 37 comes from 2(−3)^2 read as (2·−3)^2 = 36, then +1. (C) 13 squares only part. (D) −17 wrongly treats (−3)^2 as −9, giving 2(−9)+1 = −17 - the classic sign trap. The answer is A (19)." },
  { id: "t9m1-22", section: "math", domain: "Geometry and Trigonometry", difficulty: "hard", prompt: "In a right triangle, the side opposite a 30° angle is 6. What is the length of the hypotenuse?", type: "grid", gridAnswers: ["12"], explanation: "Goal: find the hypotenuse when the side opposite the 30° angle is 6. In a 30-60-90 right triangle the sides are in the ratio 1 : √3 : 2, where the side opposite 30° is the shortest (the '1') and the hypotenuse is the longest (the '2'). So the hypotenuse is twice the side opposite 30°: 2 × 6 = 12. Check: with hypotenuse 12, the side opposite 30° is 12 × (1/2) = 6, matching. A trap is multiplying by √3 (that gives the side opposite 60°, not the hypotenuse). The answer is 12." },
];

// ─────────────────────────── MATH MODULE 2 EASY (easy/med, 22) ───────────────────────────
const T9_M_M2E: SatQuestion[] = [
  { id: "t9m2e-1", section: "math", domain: "Algebra", difficulty: "easy", prompt: "If x + 9 = 23, what is the value of x?", type: "grid", gridAnswers: ["14"], explanation: "Goal: solve x + 9 = 23 for x. Subtract 9 from both sides: x = 23 − 9 = 14. Check: 14 + 9 = 23, which matches the equation. A trap is adding instead of subtracting (23 + 9 = 32), which is wrong. The answer is 14." },
  { id: "t9m2e-2", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "easy", prompt: "What is 30% of 60?", type: "mcq", choices: ["18", "20", "30", "12"], correct: 0, explanation: "Goal: find 30% of 60. Convert the percent to a decimal: 30% = 0.30. Multiply: 0.30 × 60 = 18. Check: 10% of 60 is 6, so 30% is 3 × 6 = 18. (B) 20 has no basis here. (C) 30 just repeats the percent number. (D) 12 is 20% of 60, the wrong percent. The answer is A (18)." },
  { id: "t9m2e-3", section: "math", domain: "Geometry and Trigonometry", difficulty: "easy", prompt: "A rectangle has a length of 7 and a width of 4. What is its area?", type: "grid", gridAnswers: ["28"], explanation: "Goal: find the area of a rectangle with length 7 and width 4. The area of a rectangle is length × width: 7 × 4 = 28 square units. Check: 7 × 4 = 28. A trap is computing the perimeter instead, 2(7 + 4) = 22, which answers a different question. The answer is 28." },
  { id: "t9m2e-4", section: "math", domain: "Algebra", difficulty: "easy", prompt: "If 6x = 54, what is the value of x?", type: "mcq", choices: ["9", "8", "48", "6"], correct: 0, explanation: "Goal: solve 6x = 54 for x. Divide both sides by 6: x = 54 ÷ 6 = 9. Check: 6 × 9 = 54, which matches. (B) 8 comes from 54/6 miscomputed. (C) 48 comes from 54 − 6, subtracting instead of dividing. (D) 6 just repeats the coefficient. The answer is A (9)." },
  { id: "t9m2e-5", section: "math", domain: "Advanced Math", difficulty: "easy", prompt: "What is the value of 4² − 5?", type: "grid", gridAnswers: ["11"], explanation: "Goal: evaluate 4^2 − 5. By order of operations, do the exponent first: 4^2 = 16. Then subtract: 16 − 5 = 11. Check: 16 − 5 = 11. A trap is computing 4^2 as 8 (doubling instead of squaring), which would give 3, the wrong answer. The answer is 11." },
  { id: "t9m2e-6", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "easy", prompt: "A team won 12 of its 20 games. What fraction of its games did the team win?", type: "mcq", choices: ["3/5", "12/8", "2/5", "1/2"], correct: 0, explanation: "Goal: express the fraction of games won. The team won 12 of 20, so the fraction is 12/20. Simplify by dividing top and bottom by their common factor 4: 12 ÷ 4 = 3 and 20 ÷ 4 = 5, giving 3/5. Check: 3/5 = 0.6 and 12/20 = 0.6, equal. (B) 12/8 uses games lost (8) as the denominator and is greater than 1. (C) 2/5 is the fraction lost (8/20). (D) 1/2 is not equal to 12/20. The answer is A (3/5)." },
  { id: "t9m2e-7", section: "math", domain: "Algebra", difficulty: "easy", prompt: "If 2x + 1 = 15, what is the value of x?", type: "grid", gridAnswers: ["7"], explanation: "Goal: solve 2x + 1 = 15 for x. Subtract 1 from both sides: 2x = 14. Divide by 2: x = 7. Check: 2(7) + 1 = 14 + 1 = 15, which matches. A trap is dividing 15 by 2 before subtracting the 1. The answer is 7." },
  { id: "t9m2e-8", section: "math", domain: "Geometry and Trigonometry", difficulty: "easy", prompt: "A triangle has a base of 10 and a height of 6. What is its area?", type: "grid", gridAnswers: ["30"], explanation: "Goal: find the area of a triangle with base 10 and height 6. The area of a triangle is (1/2) × base × height: (1/2)(10)(6). Compute: (1/2)(60) = 30 square units. Check: 10 × 6 = 60, and half of 60 is 30. A trap is forgetting the 1/2 factor and answering 60. The answer is 30." },
  { id: "t9m2e-9", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "easy", prompt: "A car travels 150 miles in 3 hours. What is its average speed in miles per hour?", type: "mcq", choices: ["50", "45", "30", "60"], correct: 0, explanation: "Goal: find average speed from 150 miles in 3 hours. Speed = distance ÷ time: 150 ÷ 3 = 50 miles per hour. Check: 50 mph × 3 hours = 150 miles, the given distance. (B) 45 has no basis. (C) 30 comes from a wrong division. (D) 60 comes from 180/3 or other miscomputation. The answer is A (50)." },
  { id: "t9m2e-10", section: "math", domain: "Algebra", difficulty: "easy", prompt: "If y = 4x and x = 3, what is the value of y?", type: "mcq", choices: ["12", "7", "1", "9"], correct: 0, explanation: "Goal: find y when y = 4x and x = 3. Substitute x = 3: y = 4 × 3 = 12. Check: 4 times 3 is 12. (B) 7 comes from 4 + 3, adding instead of multiplying. (C) 1 has no basis. (D) 9 comes from 3^2 or another error. The answer is A (12)." },
  { id: "t9m2e-11", section: "math", domain: "Advanced Math", difficulty: "med", prompt: "If x² = 64 and x > 0, what is the value of x?", type: "grid", gridAnswers: ["8"], explanation: "Goal: solve x^2 = 64 with x > 0. Taking the square root gives x = ±8, the two numbers whose square is 64. Since the condition is x > 0, keep the positive root: x = 8. Check: 8^2 = 64, which matches. A trap is dividing 64 by 2 to get 32; squaring is not halving. The answer is 8." },
  { id: "t9m2e-12", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "med", prompt: "The ratio of dogs to cats at a shelter is 3 to 2. If there are 18 dogs, how many cats are there?", type: "mcq", choices: ["12", "27", "9", "15"], correct: 0, explanation: "Goal: find the number of cats given dogs:cats = 3:2 and 18 dogs. Set up the proportion 3/2 = 18/cats, or note that 18 dogs equals 18 ÷ 3 = 6 'groups' of the ratio. Each group has 2 cats, so cats = 6 × 2 = 12. Check: 18 dogs to 12 cats simplifies to 3:2, the given ratio. (B) 27 wrongly scales up. (C) 9 halves the dogs. (D) 15 has no basis. The answer is A (12)." },
  { id: "t9m2e-13", section: "math", domain: "Algebra", difficulty: "med", prompt: "If 3(x − 2) = 21, what is the value of x?", type: "grid", gridAnswers: ["9"], explanation: "Goal: solve 3(x − 2) = 21 for x. Divide both sides by 3: x − 2 = 21/3 = 7. Add 2 to both sides: x = 7 + 2 = 9. (Or distribute first: 3x − 6 = 21, 3x = 27, x = 9.) Check: 3(9 − 2) = 3(7) = 21, which matches. A trap is adding 2 before dividing by 3. The answer is 9." },
  { id: "t9m2e-14", section: "math", domain: "Geometry and Trigonometry", difficulty: "med", prompt: "A circle has a diameter of 14. What is its radius?", type: "grid", gridAnswers: ["7"], explanation: "Goal: find the radius from a diameter of 14. The radius is half the diameter: r = d ÷ 2 = 14 ÷ 2 = 7. Check: a radius of 7 gives a diameter of 2 × 7 = 14, matching. A trap is multiplying by 2 instead of dividing, giving 28. The answer is 7." },
  { id: "t9m2e-15", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "med", prompt: "A phone plan costs $20 plus $0.10 per text. What is the total cost if 50 texts are sent?", type: "mcq", choices: ["$25", "$30", "$22", "$70"], correct: 0, explanation: "Goal: find the total cost of a $20 base plus $0.10 per text for 50 texts. Compute the texting charge: 0.10 × 50 = 5 dollars. Add the base: 20 + 5 = $25. Check: $0.10 each for 50 texts is $5, plus the $20 plan, totals $25. (B) $30 overcounts the text charge. (C) $22 uses only 20 texts. (D) $70 wrongly charges $1 per text. The answer is A ($25)." },
  { id: "t9m2e-16", section: "math", domain: "Algebra", difficulty: "med", prompt: "If 8 − 2x = 0, what is the value of x?", type: "mcq", choices: ["4", "2", "8", "6"], correct: 0, explanation: "Goal: solve 8 − 2x = 0 for x. Add 2x to both sides: 8 = 2x. Divide by 2: x = 4. Check: 8 − 2(4) = 8 − 8 = 0, which matches. (B) 2 comes from 8/4 or another error. (C) 8 ignores the coefficient. (D) 6 has no basis. The answer is A (4)." },
  { id: "t9m2e-17", section: "math", domain: "Advanced Math", difficulty: "med", prompt: "If g(x) = 3x − 1, what is the value of g(5)?", type: "mcq", choices: ["14", "15", "8", "16"], correct: 0, explanation: "Goal: evaluate g(x) = 3x − 1 at x = 5. Substitute: g(5) = 3(5) − 1. Multiply first: 3 × 5 = 15. Then subtract: 15 − 1 = 14. Check: 15 − 1 = 14. (B) 15 forgets to subtract the 1. (C) 8 comes from 3 + 5. (D) 16 adds 1 instead of subtracting. The answer is A (14)." },
  { id: "t9m2e-18", section: "math", domain: "Geometry and Trigonometry", difficulty: "med", prompt: "A rectangular box has dimensions 2 by 3 by 4. What is its volume?", type: "grid", gridAnswers: ["24"], explanation: "Goal: find the volume of a box with dimensions 2 by 3 by 4. The volume of a rectangular box is length × width × height: 2 × 3 × 4. Compute step by step: 2 × 3 = 6, then 6 × 4 = 24 cubic units. Check: 2 × 3 × 4 = 24. A trap is computing surface area instead of volume. The answer is 24." },
  { id: "t9m2e-19", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "med", prompt: "In a class of 25 students, 60% are girls. How many girls are in the class?", type: "mcq", choices: ["15", "10", "12", "20"], correct: 0, explanation: "Goal: find how many girls are in a class of 25 if 60% are girls. Convert the percent: 60% = 0.60. Multiply: 0.60 × 25 = 15 girls. Check: 10% of 25 is 2.5, so 60% is 6 × 2.5 = 15. (B) 10 is the number of boys (40% of 25). (C) 12 has no basis. (D) 20 overstates the percent. The answer is A (15)." },
  { id: "t9m2e-20", section: "math", domain: "Algebra", difficulty: "med", prompt: "If x/4 + 2 = 5, what is the value of x?", type: "grid", gridAnswers: ["12"], explanation: "Goal: solve x/4 + 2 = 5 for x. Subtract 2 from both sides: x/4 = 3. Multiply both sides by 4: x = 3 × 4 = 12. Check: 12/4 + 2 = 3 + 2 = 5, which matches. A trap is multiplying 5 by 4 before subtracting the 2. The answer is 12." },
  { id: "t9m2e-21", section: "math", domain: "Advanced Math", difficulty: "med", prompt: "What is the value of 2³ + 3²?", type: "mcq", choices: ["17", "13", "25", "36"], correct: 0, explanation: "Goal: evaluate 2^3 + 3^2. Compute each power: 2^3 = 2 × 2 × 2 = 8, and 3^2 = 3 × 3 = 9. Add: 8 + 9 = 17. Check: 8 + 9 = 17. (B) 13 comes from 2×3 + 3×2 + 1 type slips or treating exponents as multiplication. (C) 25 comes from (2+3)^2. (D) 36 comes from (2·3)^2. The answer is A (17)." },
  { id: "t9m2e-22", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "med", prompt: "A worker earns $18 per hour. How much does the worker earn for an 8-hour shift?", type: "grid", gridAnswers: ["144"], explanation: "Goal: find earnings for an 8-hour shift at $18 per hour. Multiply the rate by the hours: 18 × 8 = 144 dollars. Check: 18 × 8 = (10 × 8) + (8 × 8) = 80 + 64 = 144. A trap is adding the two numbers (18 + 8 = 26) instead of multiplying. The answer is 144." },
];

// ─────────────────────────── MATH MODULE 2 HARD (med/hard, 22) ───────────────────────────
const T9_M_M2H: SatQuestion[] = [
  { id: "t9m2h-1", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "If x² − 6x + 8 = 0, what is the larger solution for x?", type: "grid", gridAnswers: ["4"], explanation: "Goal: find the larger solution of x^2 − 6x + 8 = 0. Factor: find two numbers multiplying to 8 and adding to −6, namely −2 and −4, so (x − 2)(x − 4) = 0. Setting each factor to 0 gives x = 2 or x = 4. The larger is 4. Check: 4^2 − 6(4) + 8 = 16 − 24 + 8 = 0, which works. The trap is gridding the smaller root (2) when the question asks for the larger. The answer is 4." },
  { id: "t9m2h-2", section: "math", domain: "Algebra", difficulty: "hard", prompt: "If 2x + 5y = 31 and x = 3, what is the value of y?", type: "mcq", choices: ["5", "4", "6", "3"], correct: 0, explanation: "Goal: solve 2x + 5y = 31 with x = 3. Substitute x = 3: 2(3) + 5y = 31, so 6 + 5y = 31. Subtract 6: 5y = 25. Divide by 5: y = 5. Check: 2(3) + 5(5) = 6 + 25 = 31, which matches. (B) 4 comes from solving 5y = 20. (C) 6 and (D) 3 do not satisfy 5y = 25. The answer is A (5)." },
  { id: "t9m2h-3", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "If 2^(x+1) = 32, what is the value of x?", type: "grid", gridAnswers: ["4"], explanation: "Goal: solve 2^(x+1) = 32. Rewrite 32 as a power of 2: 2^5 = 32. So 2^(x+1) = 2^5, and with equal bases the exponents are equal: x + 1 = 5. Subtract 1: x = 4. Check: 2^(4+1) = 2^5 = 32, which matches. A trap is solving x + 1 = 32 or forgetting the +1 in the exponent. The answer is 4." },
  { id: "t9m2h-4", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "hard", prompt: "A population of 200 bacteria doubles every hour. How many bacteria are there after 3 hours?", type: "mcq", choices: ["1600", "800", "600", "1200"], correct: 0, explanation: "Goal: find the population after 3 hours when 200 bacteria double every hour. Doubling for 3 hours multiplies by 2 three times, a factor of 2^3 = 8. So the population is 200 × 8 = 1600. Check hour by hour: 200 → 400 → 800 → 1600. (B) 800 stops at 2 hours. (C) 600 adds 200 three times (linear, not doubling). (D) 1200 uses 200 × 6. The answer is A (1600)." },
  { id: "t9m2h-5", section: "math", domain: "Geometry and Trigonometry", difficulty: "hard", prompt: "A right triangle has legs of length 5 and 12. What is the length of the hypotenuse?", type: "grid", gridAnswers: ["13"], explanation: "Goal: find the hypotenuse of a right triangle with legs 5 and 12. Use the Pythagorean theorem c^2 = a^2 + b^2: c^2 = 5^2 + 12^2 = 25 + 144 = 169. Take the square root: c = √169 = 13. Check: 5^2 + 12^2 = 25 + 144 = 169 = 13^2 (the 5-12-13 triple). A trap is adding the legs (5 + 12 = 17) instead of using the theorem. The answer is 13." },
  { id: "t9m2h-6", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "If f(x) = x² + 2x, what is the value of f(f(1))?", type: "mcq", choices: ["15", "8", "3", "24"], correct: 0, explanation: "Goal: compute f(f(1)) for f(x) = x^2 + 2x. Work from the inside out. First f(1) = 1^2 + 2(1) = 1 + 2 = 3. Then apply f to that result: f(3) = 3^2 + 2(3) = 9 + 6 = 15. Check: f(1) = 3, and f(3) = 15. (B) 8 mistakenly computes f(2) or stops early. (C) 3 is only f(1), not the full composition. (D) 24 squares the wrong value. The answer is A (15)." },
  { id: "t9m2h-7", section: "math", domain: "Algebra", difficulty: "hard", prompt: "The line y = mx − 4 passes through the point (2, 6). What is the value of m?", type: "grid", gridAnswers: ["5"], explanation: "Goal: find m so that y = mx − 4 passes through (2, 6). Substitute x = 2 and y = 6: 6 = m(2) − 4, so 6 = 2m − 4. Add 4 to both sides: 10 = 2m. Divide by 2: m = 5. Check: y = 5(2) − 4 = 10 − 4 = 6, matching the point. A trap is forgetting to add the 4 back before dividing. The answer is 5." },
  { id: "t9m2h-8", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "hard", prompt: "An $80 jacket is marked up by 25%, then that price is discounted by 20%. What is the final price?", type: "mcq", choices: ["$80", "$84", "$76", "$90"], correct: 0, explanation: "Goal: find the final price after an $80 jacket is marked up 25% then discounted 20%. Markup: 80 × 1.25 = 100. Discount on the new price: 100 × (1 − 0.20) = 100 × 0.80 = $80. Check: a 25% increase then a 20% decrease gives 1.25 × 0.80 = 1.00, so the price returns to the original $80. (B) $84 and (D) $90 ignore that the discount applies to the marked-up price. (C) $76 subtracts the percents (25 − 20 = 5%), which is invalid because they apply to different bases. The answer is A ($80)." },
  { id: "t9m2h-9", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "If x² + y² = 25 and xy = 12, what is the value of (x + y)²?", type: "grid", gridAnswers: ["49"], explanation: "Goal: find (x + y)^2 given x^2 + y^2 = 25 and xy = 12. Expand the square: (x + y)^2 = x^2 + 2xy + y^2. Group the known parts: = (x^2 + y^2) + 2(xy) = 25 + 2(12) = 25 + 24 = 49. Check: this uses the identity directly; if x = 3, y = 4 then x^2 + y^2 = 25, xy = 12, and (3 + 4)^2 = 49. A trap is forgetting the middle term 2xy and answering 25. The answer is 49." },
  { id: "t9m2h-10", section: "math", domain: "Geometry and Trigonometry", difficulty: "hard", prompt: "A cylinder has a radius of 3 and a height of 5. What is its volume? (Use π.)", type: "mcq", choices: ["45π", "15π", "30π", "75π"], correct: 0, explanation: "Goal: find the volume of a cylinder with radius 3 and height 5. The volume formula is V = πr^2h. Substitute: V = π(3^2)(5) = π(9)(5) = 45π. Check: 9 × 5 = 45, so V = 45π. (B) 15π forgets to square the radius (π·3·5). (C) 30π uses the diameter or doubles wrongly. (D) 75π uses r = √5 or other slip. The answer is A (45π)." },
  { id: "t9m2h-11", section: "math", domain: "Algebra", difficulty: "hard", prompt: "If 4x − 3y = 5 and 2x + 3y = 13, what is the value of x?", type: "grid", gridAnswers: ["3"], explanation: "Goal: solve 4x − 3y = 5 and 2x + 3y = 13 for x. Add the equations so the y-terms cancel (−3y + 3y = 0): (4x + 2x) = 5 + 13, giving 6x = 18. Divide by 6: x = 3. Check: with x = 3, the second equation gives 6 + 3y = 13, so y = 7/3; then 4(3) − 3(7/3) = 12 − 7 = 5, matching the first. A trap is subtracting the equations instead of adding, which would not eliminate y. The answer is 3." },
  { id: "t9m2h-12", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "The product of the roots of x² − 5x + 6 = 0 is what value?", type: "mcq", choices: ["6", "5", "-6", "1"], correct: 0, explanation: "Goal: find the product of the roots of x^2 − 5x + 6 = 0. For a monic quadratic x^2 + bx + c, the product of the roots equals the constant c. Here c = 6, so the product is 6. Confirm by factoring: (x − 2)(x − 3) = 0 gives roots 2 and 3, and 2 × 3 = 6. (B) 5 is the sum of the roots (−b), not the product. (C) −6 has the wrong sign. (D) 1 has no basis. The answer is A (6)." },
  { id: "t9m2h-13", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "hard", prompt: "The average of five numbers is 14. If one number, 10, is removed, what is the average of the remaining four?", type: "grid", gridAnswers: ["15"], explanation: "Goal: find the new average after removing one number. The average of five numbers is 14, so their total is 5 × 14 = 70. Remove the number 10: new total = 70 − 10 = 60. Now there are four numbers, so the new average = 60 ÷ 4 = 15. Check: 4 × 15 = 60, and 60 + 10 = 70 = 5 × 14, consistent. A trap is dividing 70 by 4 without first subtracting the removed value. The answer is 15." },
  { id: "t9m2h-14", section: "math", domain: "Geometry and Trigonometry", difficulty: "hard", prompt: "Two similar triangles have a scale factor of 3. If the smaller triangle has an area of 5, what is the area of the larger one?", type: "grid", gridAnswers: ["45"], explanation: "Goal: find the larger triangle's area given a scale factor of 3 and a smaller area of 5. For similar figures, areas scale by the SQUARE of the linear scale factor, so the area multiplies by 3^2 = 9. Larger area = 5 × 9 = 45. Check: lengths triple, so area grows by 3 × 3 = 9 times. A trap is multiplying the area by 3 (the linear factor) to get 15, ignoring that area scales by the square. The answer is 45." },
  { id: "t9m2h-15", section: "math", domain: "Algebra", difficulty: "hard", prompt: "If |2x − 6| = 10 and x > 0, what is the value of x?", type: "mcq", choices: ["8", "2", "-2", "5"], correct: 0, explanation: "Goal: solve |2x − 6| = 10 with x > 0. An absolute-value equation splits into two cases. Case 1: 2x − 6 = 10 → 2x = 16 → x = 8. Case 2: 2x − 6 = −10 → 2x = −4 → x = −2. The condition x > 0 rules out −2, leaving x = 8. Check: |2(8) − 6| = |10| = 10, which matches. (B) 2 satisfies neither case. (C) −2 is the excluded negative root. (D) 5 does not work. The answer is A (8)." },
  { id: "t9m2h-16", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "If √(x + 4) = 6, what is the value of x?", type: "grid", gridAnswers: ["32"], explanation: "Goal: solve √(x + 4) = 6. Square both sides to remove the radical: x + 4 = 6^2 = 36. Subtract 4: x = 36 − 4 = 32. Check: √(32 + 4) = √36 = 6, which matches. A trap is computing 6 × 2 = 12 (doubling instead of squaring) or forgetting to subtract the 4. The answer is 32." },
  { id: "t9m2h-17", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "hard", prompt: "A solution is 40% acid. How many liters of acid are in 25 liters of the solution?", type: "mcq", choices: ["10", "12", "8", "15"], correct: 0, explanation: "Goal: find the liters of acid in 25 liters of a 40% acid solution. Convert the percent: 40% = 0.40. Multiply by the total volume: 0.40 × 25 = 10 liters of acid. Check: 10 liters out of 25 is 10/25 = 0.40 = 40%, the given concentration. (B) 12, (C) 8, and (D) 15 do not match 0.40 × 25. The answer is A (10)." },
  { id: "t9m2h-18", section: "math", domain: "Algebra", difficulty: "hard", prompt: "If 3x + 2 = 5x − 8, what is the value of x?", type: "grid", gridAnswers: ["5"], explanation: "Goal: solve 3x + 2 = 5x − 8 for x. Subtract 3x from both sides to gather the x-terms: 2 = 2x − 8. Add 8 to both sides: 10 = 2x. Divide by 2: x = 5. Check: left side 3(5) + 2 = 17; right side 5(5) − 8 = 17; equal. A trap is subtracting 5x from the left and mishandling the signs. The answer is 5." },
  { id: "t9m2h-19", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "What is the x-coordinate of the vertex of the parabola y = x² − 8x + 3?", type: "mcq", choices: ["4", "-4", "8", "3"], correct: 0, explanation: "Goal: find the x-coordinate of the vertex of y = x^2 − 8x + 3. For a parabola y = ax^2 + bx + c, the vertex is at x = −b/(2a). Here a = 1 and b = −8, so x = −(−8)/(2·1) = 8/2 = 4. Check: the parabola is symmetric about x = 4. (B) −4 has the wrong sign (uses b instead of −b). (C) 8 forgets to divide by 2a. (D) 3 is the constant term c, not the vertex. The answer is A (4)." },
  { id: "t9m2h-20", section: "math", domain: "Geometry and Trigonometry", difficulty: "hard", prompt: "An equilateral triangle has a perimeter of 27. What is the length of one side?", type: "grid", gridAnswers: ["9"], explanation: "Goal: find one side of an equilateral triangle with perimeter 27. An equilateral triangle has three equal sides, so each side is the perimeter divided by 3: 27 ÷ 3 = 9. Check: 3 sides × 9 = 27, the given perimeter. A trap is dividing by 2 (as if for a base/height) instead of by 3. The answer is 9." },
  { id: "t9m2h-21", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "hard", prompt: "A line of best fit is y = 2.5x + 4. What value does it predict for y when x = 6?", type: "mcq", choices: ["19", "15", "21", "16"], correct: 0, explanation: "Goal: use the line of best fit y = 2.5x + 4 to predict y when x = 6. Substitute x = 6: y = 2.5(6) + 4. Multiply first: 2.5 × 6 = 15. Add 4: 15 + 4 = 19. Check: 15 + 4 = 19. (B) 15 forgets to add the intercept 4. (C) 21 comes from 2.5(7) + 4 or other slip. (D) 16 adds wrong. The answer is A (19)." },
  { id: "t9m2h-22", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "If (x + 3)(x − 5) = 0, what is the sum of all possible values of x?", type: "grid", gridAnswers: ["2"], explanation: "Goal: find the sum of all x with (x + 3)(x − 5) = 0. By the zero-product property, each factor can be zero: x + 3 = 0 gives x = −3, and x − 5 = 0 gives x = 5. Their sum is −3 + 5 = 2. Check: the roots −3 and 5 both make a factor zero. A trap is reading the roots with flipped signs (x = 3 and x = −5) and summing to −2. The answer is 2." },
];

